INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(39811, 'Exodus 29:32', 'Exodus', 29, 32, 'د سپېڅلې خېمې د دروازې په خولې کې دې هارون او د هغه زامن د پسه غوښه او هغه ډوډۍ چې په ټوکرۍ کې پاتې ده، وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_32.mp3', '', 1761754199, 1761754199),
(39812, 'Exodus 29:33', 'Exodus', 29, 33, 'یوازې هغوی کولای شي چې د ټاکنې په مراسمو کې هغه غوښه او ډوډۍ چې د هغوی د کفارې د ادا کولو دپاره ورڅخه کار اخیستل کیږي، وخوري. عادي خلک نه شي کولای هغه وخوري، ځکه چې دا شیان سپېڅلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_33.mp3', '', 1761754199, 1761754199),
(39813, 'Exodus 29:34', 'Exodus', 29, 34, 'که چېرې یو څه غوښه یا ډوډۍ ونه خوړل شي او تر سهاره پورې پاتې شي، هغه وسوځوه. هغه باید ونه خوړل شي، ځکه چې سپېڅلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_34.mp3', '', 1761754199, 1761754199),
(39814, 'Exodus 29:35', 'Exodus', 29, 35, 'لکه څنګه چې ما درته حکم کړی دی د هارون او د هغه د زامنو د ټاکنې مراسم دې په اوو ورځو کې سرته ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_35.mp3', '', 1761754199, 1761754199),
(39815, 'Exodus 29:36', 'Exodus', 29, 36, 'ته باید هره ورځ یو غویی حلال کړې او ماته یې وړاندې کړې، ترڅو د هغوی ګناه وبخښم او د قربانۍ ځای پاک شي. برسېره پردې باید د زیتونو تېل واخلې او د قربانۍ ځای ورباندې مسح کړې چې سپېڅلی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_36.mp3', '', 1761754199, 1761754199),
(39816, 'Exodus 29:37', 'Exodus', 29, 37, 'اووه ورځې دا کار وکړه. بیا به د قربانۍ ځای دومره سپېڅلی شي چې هرڅوک یا هر شی چې د هغه سره ولګیږي، هغه به هم سپېڅلی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_37.mp3', '', 1761754199, 1761754199),
(39817, 'Exodus 29:38', 'Exodus', 29, 38, 'ته باید هره ورځ د قربانۍ په ځای باندې دوه یو کلن وري قرباني کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_38.mp3', '', 1761754199, 1761754199),
(39818, 'Exodus 29:39', 'Exodus', 29, 39, 'یو په سهار کې قرباني کړه او بل په ماښام کې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_39.mp3', '', 1761754199, 1761754199),
(39819, 'Exodus 29:40', 'Exodus', 29, 40, 'د لومړني وري سره یو کیلو ګرام ښه اوړه وړاندې کړه چې یو لیتر سوچه د زیتونو تېل ورسره ګډ وي او د څښلو د نذرانې په توګه یو لیتر شراب هم وړاندې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_40.mp3', '', 1761754199, 1761754199),
(39820, 'Exodus 29:41', 'Exodus', 29, 41, 'دوهم وری په ماښام کې قرباني کړه او د هغه سره هماغه اندازه اوړه، د زیتونو تېل او شراب وړاندې کړه لکه څنګه چې په سهار کې دې وکړل. دا زما دپاره یوه سوځېدونکې نذرانه ده او د هغې بوی په ما باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_41.mp3', '', 1761754199, 1761754199),
(39821, 'Exodus 29:42', 'Exodus', 29, 42, 'دا سوځېدونکې نذرانه دې د تل دپاره هره ورځ د سپېڅلې خېمې د دروازې په خولې کې زما حضور ته وړاندې شي. زه به هلته د اسراییلو د خلکو سره لیدنه او کتنه وکړم او تا سره به خبرې وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_42.mp3', '', 1761754199, 1761754199),
(39822, 'Exodus 29:43', 'Exodus', 29, 43, 'د اسراییلیانو سره به هم هلته لیدنه او کتنه وکړم او هغه ځای به زما د جلال په وسیله پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_43.mp3', '', 1761754199, 1761754199),
(39823, 'Exodus 29:44', 'Exodus', 29, 44, 'نو زه به خېمه او د قربانۍ ځای سپېڅلی کړم او هارون او د هغه زامن به د دې دپاره پاک کړم چې د کاهنانو په توګه زما خدمت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_44.mp3', '', 1761754199, 1761754199),
(39824, 'Exodus 29:45', 'Exodus', 29, 45, 'بیا به زه د اسراییلو د خلکو په منځ کې اوسېږم او د هغوی خدای به یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_45.mp3', '', 1761754199, 1761754199),
(39825, 'Exodus 29:46', 'Exodus', 29, 46, 'هغوی به په دې پوه شي چې زه د هغوی څښتن خدای یم، چا چې هغوی له مصر څخه راوویستل، ترڅو د هغوی په منځ کې واوسېږم. زه د هغوی څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus29_verse_46.mp3', '', 1761754199, 1761754199),
(39826, 'Psalms 20:1', 'Psalms', 20, 1, 'په سختۍ کې دې څښتن کاندي قبوله ستا دعا د یعقوب خدای دې ساتنه وکړي ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms20_verse_1.mp3', '', 1761754199, 1761754199),
(39827, 'Psalms 20:2', 'Psalms', 20, 2, 'له خپل سپېڅلي ځای نه دې کومک واستوي تاته د صهیون له غره دې مرسته وکړي ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms20_verse_2.mp3', '', 1761754199, 1761754199),
(39828, 'Psalms 20:3', 'Psalms', 20, 3, 'کړي رایادې دې ستا ټولې نذرانې کړي قبولې دې ستا ټولې سوځېدونکې قربانۍ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms20_verse_3.mp3', '', 1761754199, 1761754199),
(39829, 'Psalms 20:4', 'Psalms', 20, 4, 'کړي پوره دې هغه ستا د زړه ارمان او د ستا ټول پلانونه دې کامیاب کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms20_verse_4.mp3', '', 1761754199, 1761754199),
(39830, 'Psalms 20:5', 'Psalms', 20, 5, 'بیا به چیغې د خوشحالۍ ستا په بریا کړو د خپل خدای په نوم به جګ کړو بیرغونه کړي څښتن دې ټول قبول ستا سوالونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms20_verse_5.mp3', '', 1761754199, 1761754199),
(39831, 'Psalms 20:6', 'Psalms', 20, 6, 'اوس پوهېږم چې څښتن خپل غوره کړی پاچا ژغوري کړي دعا به یې قبوله له خپل پاک ځایه اسمانه ور به کړي په خپل قدرت هغه ته لویې کامیابۍ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms20_verse_6.mp3', '', 1761754199, 1761754199),
(39832, 'Psalms 20:7', 'Psalms', 20, 7, 'ځینې توکل کوي ګاډیو جنګي خپلو باندې ځینې توکل کړي په اسونو باندې زمونږ توکل دی په نامه د خپل څښتن خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms20_verse_7.mp3', '', 1761754199, 1761754199),
(39833, 'Psalms 20:8', 'Psalms', 20, 8, 'داسې خلک به ښوییږي او رالویږي خو مونږه به پاڅېږو ټینګ ودرېږو به', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms20_verse_8.mp3', '', 1761754199, 1761754199),
(39834, 'Psalms 20:9', 'Psalms', 20, 9, 'ای څښتنه، ته پاچا ته بری ورکړه د کومک دپاره زمونږه فریاد واوره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms20_verse_9.mp3', '', 1761754199, 1761754199),
(39835, 'Proverbs 14:1', 'Proverbs', 14, 1, 'هوښیاره ښځه خپل کور ودانوي خو جاهله ښځه خپل کور په خپل لاس ورانوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_1.mp3', '', 1761754199, 1761754199),
(39836, 'Proverbs 14:2', 'Proverbs', 14, 2, 'څوک چې له څښتن څخه وېریږي هغه په سمه لار ځي خو څوک چې په غلطو لارو روان وي څښتن سپکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_2.mp3', '', 1761754199, 1761754199),
(39837, 'Proverbs 14:3', 'Proverbs', 14, 3, 'د جاهل له کبرجنې ژبې نه د سزا شنه لښته جوړیږي خو د هوښیارانو د خولې خبرې له هغوی ساتنه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_3.mp3', '', 1761754199, 1761754199),
(39838, 'Proverbs 14:4', 'Proverbs', 14, 4, 'چېرته چې څاروي نه وي هلته اخور خالي وي خو د غویي په زور ډېر حاصل لاسته راځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_4.mp3', '', 1761754199, 1761754199),
(39839, 'Proverbs 14:5', 'Proverbs', 14, 5, 'رښتینی شاهد هېڅکله دروغ نه وایي خو دروغجن شاهد تل دروغ بادوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_5.mp3', '', 1761754199, 1761754199),
(39840, 'Proverbs 14:6', 'Proverbs', 14, 6, 'ملنډې وهونکی حکمت لټوي خو هېڅ نه مومي خو د عقل خاوند علم په اسانۍ لاسته راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_6.mp3', '', 1761754199, 1761754199),
(39841, 'Proverbs 14:7', 'Proverbs', 14, 7, 'له کم‌عقل نه لېرې لاړ شه ځکه چې له خولې نه به یې علم حاصل نه کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_7.mp3', '', 1761754199, 1761754199),
(39842, 'Proverbs 14:8', 'Proverbs', 14, 8, 'ځیرک انسان په خپل حکمت خپله لار پېژني خو د کم‌عقلانو جهالت د ګمراهۍ سبب ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_8.mp3', '', 1761754199, 1761754199),
(39843, 'Proverbs 14:9', 'Proverbs', 14, 9, 'جاهل د ګناه د تاوان په نذرانه پورې خاندي خو صادقان د څښتن رضا او خوشحالي غواړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_9.mp3', '', 1761754199, 1761754199),
(39844, 'Proverbs 14:10', 'Proverbs', 14, 10, 'یوازې د انسان زړه په خپل خفګان ښه پوهیږي او هېڅوک د هغه په خوشحالۍ کې برخه نه شي اخیستلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_10.mp3', '', 1761754199, 1761754199),
(39845, 'Proverbs 14:11', 'Proverbs', 14, 11, 'د بدکارانو کور به وران شي خو د صادقانو خېمه به ودانه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_11.mp3', '', 1761754199, 1761754199),
(39846, 'Proverbs 14:12', 'Proverbs', 14, 12, 'د یو انسان په نظر یوه لار سمه ښکاري خو په اخر کې هغه په مرګ پای ته رسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_12.mp3', '', 1761754199, 1761754199),
(39847, 'Proverbs 14:13', 'Proverbs', 14, 13, 'حتی په خندا کې زړه هم خفه کیږي او د خوشحالۍ په اخر کې خفګان پاتې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_13.mp3', '', 1761754199, 1761754199),
(39848, 'Proverbs 14:14', 'Proverbs', 14, 14, 'له سمې لارې نه مخ اړوونکی به د خپل کار حاصل وګوري خو نېک انسان به د خپل عمل په مېوه نور هم موړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_14.mp3', '', 1761754199, 1761754199),
(39849, 'Proverbs 14:15', 'Proverbs', 14, 15, 'ساده سړی په هرڅه باندې باور کوي خو ځیرک انسان د هر قدم په اخیستلو کې فکر کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_15.mp3', '', 1761754199, 1761754199),
(39850, 'Proverbs 14:16', 'Proverbs', 14, 16, 'د حکمت خاوند په احتیاط له بدو نه خپل ځان ساتي خو کم‌عقل انسان په ځان ډاډمن او د هېڅ شی پروا نه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_16.mp3', '', 1761754199, 1761754199),
(39851, 'Proverbs 14:17', 'Proverbs', 14, 17, 'غوسه ناک خلک د جهالت کارونه کوي او له مکرجن انسان نه خلک کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_17.mp3', '', 1761754199, 1761754199),
(39852, 'Proverbs 14:18', 'Proverbs', 14, 18, 'جهالت د ساده خلکو په نصیب وي خو د ځیرکه خلکو په سر به د علم تاج وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_18.mp3', '', 1761754199, 1761754199),
(39853, 'Proverbs 14:19', 'Proverbs', 14, 19, 'بدکاران به د ښو خلکو په مخکې سر ټیټې شي او شر اچوونکي به د نېکانو په دروازو کې په ګونډو شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_19.mp3', '', 1761754199, 1761754199),
(39854, 'Proverbs 14:20', 'Proverbs', 14, 20, 'د مسکین انسان نه خپل ګاونډي هم کرکه کوي خو شتمن انسان ډېر دوستان لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_20.mp3', '', 1761754199, 1761754199),
(39855, 'Proverbs 14:21', 'Proverbs', 14, 21, 'څوک چې خپل ګاونډي سپک ګڼي نو ګناه کوي او بختور دی هغه څوک چې په عاجزانو رحم کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_21.mp3', '', 1761754199, 1761754199),
(39856, 'Proverbs 14:22', 'Proverbs', 14, 22, 'څوک چې بدې ارادې لري بې‌لارې کیږي خو څوک چې نېکې ارادې لري نو مینه او وفا یې په برخه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_22.mp3', '', 1761754199, 1761754199),
(39857, 'Proverbs 14:23', 'Proverbs', 14, 23, 'ټول سخت کارونه د ابادۍ سبب ګرځي خو تشې خبرې حتمي نېستي راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_23.mp3', '', 1761754199, 1761754199),
(39858, 'Proverbs 14:24', 'Proverbs', 14, 24, 'د هوښیارانو دولت د هغوی د سر تاج دی خو د کم‌عقلانو ناپوهي د هغوی جهالت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_24.mp3', '', 1761754199, 1761754199),
(39859, 'Proverbs 14:25', 'Proverbs', 14, 25, 'رښتینی شاهد د خلکو ژوند ژغوري خو د دروغجن له خولې نه د ټګۍ خبرې راوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_25.mp3', '', 1761754199, 1761754199),
(39860, 'Proverbs 14:26', 'Proverbs', 14, 26, 'له څښتن څخه وېره د انسان دپاره د امن ټینګه کلا ده او د هغه د اولادونو دپاره کلکه پناه ګاه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_26.mp3', '', 1761754199, 1761754199),
(39861, 'Proverbs 14:27', 'Proverbs', 14, 27, 'له څښتن څخه وېره د ژوند سرچینه ده چې انسان د مرګ له دامونو څخه ژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_27.mp3', '', 1761754199, 1761754199),
(39862, 'Proverbs 14:28', 'Proverbs', 14, 28, 'د پاچا شان او شوکت په ډېرو خلکو جوړ وي خو بې‌ولسه مشر له تباهۍ سره مخامخ کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_28.mp3', '', 1761754199, 1761754199),
(39863, 'Proverbs 14:29', 'Proverbs', 14, 29, 'څوک چې زر نه په قهریږي د ډېرې پوهې خاوند وي خو غوسه ناک سړی خپل جهالت ښکاره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_29.mp3', '', 1761754199, 1761754199),
(39864, 'Proverbs 14:30', 'Proverbs', 14, 30, 'ارام فکر بدن ته روغتیا ورکوي خو کینه هډوکي وراسته کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_30.mp3', '', 1761754199, 1761754199),
(39865, 'Proverbs 14:31', 'Proverbs', 14, 31, 'څوک چې په غریبانو ظلم کوي نو د هغوی د خالق سپکاوی کوي خو څوک چې په مظلومانو رحم کوي نو د خالق درناوی کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_31.mp3', '', 1761754199, 1761754199),
(39866, 'Proverbs 14:32', 'Proverbs', 14, 32, 'بدکاره انسان په خپلو عملونو ځان تباه کوي خو نېک انسان د مرګ په خوله کې هم پناه اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_32.mp3', '', 1761754199, 1761754199),
(39867, 'Proverbs 14:33', 'Proverbs', 14, 33, 'حکمت د عقلمن انسان په زړه کې تلپاتې وي او د کم‌عقلانو په منځ کې هم خپل ځان څرګندوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_33.mp3', '', 1761754199, 1761754199),
(39868, 'Proverbs 14:34', 'Proverbs', 14, 34, 'په صداقت سره یو قوم سرلوړی کیږي خو ګناه د هغوی د رسوایۍ سبب ګرځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_34.mp3', '', 1761754199, 1761754199),
(39869, 'Proverbs 14:35', 'Proverbs', 14, 35, 'پاچا د هوښیار خدمتګار څخه خوشحالیږي خو څوک چې د شرم کارونه کوي د هغه د قهر سبب کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs14_verse_35.mp3', '', 1761754199, 1761754199),
(39870, 'Ezra 10:1', 'Ezra', 10, 1, 'په داسې حال کې چې عزرا د خدای د کور په مخکې په دعا کې په سجده پرېوت، هغه ژړل او د قوم په ګناهونو باندې یې اقرار کاوه. د اسراییلیانو یوه ډېره لویه ډله چې سړي، ښځې او ماشومان په کې وو د هغه په شاوخوا راټول شول او ډېر سخت یې وژړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_1.mp3', '', 1761754199, 1761754199),
(39871, 'Ezra 10:2', 'Ezra', 10, 2, 'بیا شکنیا د یحییل زوی چې د عیلام د طایفې څخه ؤ، عزرا ته وویل: «مونږ د پردیو قومونو د ښځو سره په ودونو کولو د خپل خدای سره خپله وفاداري ماته کړه، خو بیاهم د اسراییلو د قوم دپاره هیله شته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_2.mp3', '', 1761754199, 1761754199),
(39872, 'Ezra 10:3', 'Ezra', 10, 3, 'راځئ اوس د خپل خدای سره لوظ وکړو چې مونږ به دا ټولې ښځې او د هغوی اولادونه وشړو. مونږ به دا کار ستاسو او د هغو خلکو د مشورې سره سم چې د خدای حکم ته درناوی کوي، وکړو. مونږ به د خدای د شریعت د غوښتنې سره سم عمل وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_3.mp3', '', 1761754199, 1761754199),
(39873, 'Ezra 10:4', 'Ezra', 10, 4, 'راپاڅېږه، دا ستا مسوولیت دی. مونږ ستا شاته ولاړ یو، نو په زړورتیا سره دا کار وکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_4.mp3', '', 1761754199, 1761754199),
(39874, 'Ezra 10:5', 'Ezra', 10, 5, 'نو عزرا د کاهنانو مشرانو، لاویانو او نورو اسراییلیانو ته قسم ورکړ چې دوی به د شکنیا د مشورې څخه پیروي وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_5.mp3', '', 1761754199, 1761754199),
(39875, 'Ezra 10:6', 'Ezra', 10, 6, 'بیا عزرا د خدای د کور د مخې نه د الیاشیب د زوی یهوحانان د خوب کوټې ته ورغی او هلته یې شپه تېره کړه. هغه نه څه وخوړل او نه یې څه وڅښل، ځکه چې د جلاوطنو خلکو په بې وفایۍ باندې یې ویر کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_6.mp3', '', 1761754199, 1761754199),
(39876, 'Ezra 10:9', 'Ezra', 10, 9, 'په درېو ورځو کې، د نهمې میاشتې په شلمه ورځ هغه ټول خلک چې د یهودا او بنیامین په سیمو کې اوسېدل، اورشلیم ته راغلل او د خدای د کور په حوېلۍ کې سره راټول شول. هغوی لړزېدل، ځکه چې له یوې خوا دا یوه ډېره مهمه غونډه وه او بله دا چې هلته په سخت باران کې ناست وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_9.mp3', '', 1761754199, 1761754199),
(39877, 'Ezra 10:10', 'Ezra', 10, 10, 'عزرا کاهن پاڅېد او هغوی ته یې وویل: «تاسو بې وفایي کړې ده او د پردیو قومونو د ښځو سره په ودونو کولو باندې مو د اسراییلو ګناهونه زیات کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_10.mp3', '', 1761754199, 1761754199),
(39878, 'Ezra 10:11', 'Ezra', 10, 11, 'نو اوس د خپلو نیکونو د څښتن خدای په مخکې د خپلو ګناهونو اقرار وکړئ او هغه کار وکړئ چې هغه ورباندې خوشحالیږي. د هغو پردیو خلکو نه چې زمونږ په خاوره کې اوسیږي، بېل شئ او د پردیو ښځو څخه ځانونه خلاص کړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_11.mp3', '', 1761754199, 1761754199),
(39879, 'Ezra 10:12', 'Ezra', 10, 12, 'ټولو خلکو په لوړ اواز ځواب ورکړ: «تاسو په حقه خبره کوئ. څنګه چې تاسو وایئ هماغسې باید وکړو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_12.mp3', '', 1761754199, 1761754199),
(39880, 'Ezra 10:13', 'Ezra', 10, 13, 'خو هغوی زیاته کړه: «دلته ډېر زیات خلک دي او سخت باران وریږي. مونږ نه شو کولای چې دلته دباندې ودرېږو. دا داسې کار نه دی چې په یوې یا دوه ورځو کې سرته ورسیږي، ځکه چې په مونږ کې ډېر خلک په دې ګناه اخته دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_13.mp3', '', 1761754199, 1761754199),
(39881, 'Ezra 10:14', 'Ezra', 10, 14, 'پرېږدئ چې زمونږ مشران په اورشلیم کې پاتې شي او د دې موضوع مسوولیت په غاړه واخلي. بیا هغه څوک چې ښځه یې د پردي قوم څخه وي، هغه دې د خپل ښار د مشرانو او قاضیانو سره یوځای په ټاکلي وخت راشي. په دې ډول به د دې موضوع په هکله زمونږ د خدای سخت قهر سوړ شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_14.mp3', '', 1761754199, 1761754199),
(39882, 'Ezra 10:15', 'Ezra', 10, 15, 'د عساهیل د زوی یوناتان او د تقوه د زوی یحزیا او د هغوی د ملاتړ کوونکو یعنې مشلام او لاوي شبتای څخه پرته نور هېچا د دې پلان سره مخالفت ونه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_15.mp3', '', 1761754199, 1761754199),
(39883, 'Ezra 10:16', 'Ezra', 10, 16, 'راستانه شویو جلاوطنو خلکو دا پلان ومنلو، نو عزرا کاهن د طایفو د مشرانو له منځ نه کسان وټاکل او د هغو نومونه یې ولیکل. د لسمې میاشتې په لومړۍ ورځ هغوی کښېناستل او خپله څېړنه یې پیل کړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_16.mp3', '', 1761754199, 1761754199),
(39884, 'Ezra 10:17', 'Ezra', 10, 17, 'او هغوی د لومړۍ میاشتې په لومړۍ ورځ د هغو خلکو ټولې قضیې وڅېړلې چې د پردي قوم څخه یې ښځې کړې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_17.mp3', '', 1761754199, 1761754199),
(39885, 'Ezra 10:18', 'Ezra', 10, 18, 'د هغو خلکو لست چې د پردي قوم څخه یې ښځې کړې وې: د طایفو له مخې د کاهنانو لست: د یوصاداق د زوی یشوع او د هغه د ورونو د طایفې څخه: معسیا، الیعازر، یاریب او جدلیا.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_18.mp3', '', 1761754199, 1761754199),
(39886, 'Ezra 10:19', 'Ezra', 10, 19, 'هغوی لوظ وکړ چې خپلې ښځې به وشړي. د خپلو ګناهونو په خاطر یې یو پسه د قربانۍ په توګه وړاندې کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_19.mp3', '', 1761754199, 1761754199),
(39887, 'Ezra 10:20', 'Ezra', 10, 20, 'د یمیر له طایفې څخه: حناني او زبدیا.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_20.mp3', '', 1761754199, 1761754199),
