(39889, 'Ezra 10:22', 'Ezra', 10, 22, 'د فشحور له طایفې څخه: الیوعینای، معسیا، اسماعیل، نتنییل، یوزاباد او العاسه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra10_verse_22.mp3', '', 1761754199, 1761754199),
